     1	package hotel.notifications;
     2	
     3	import hotel.documents.TextFormat;
     4	import hotel.messages.EmailSender;
     5	import hotel.reservations.Reservation;
     6	import hotel.reservations.ReservationListener;
     7	import hotel.rooms.Room;
     8	
     9	/** Finance hears about every payment and every refund (a cancellation with nothing to refund is not news). */
    10	public final class FinanceNotice implements ReservationListener {
    11	
    12	    static final String FINANCE_EMAIL = "financeiro@pousadamarealta.com.br";
    13	
    14	    private final EmailSender emailSender;
    15	
    16	    public FinanceNotice(EmailSender emailSender) {
    17	        this.emailSender = emailSender;
    18	    }
    19	
    20	    @Override
    21	    public void confirmed(Reservation reservation, Room room) {
    22	        emailSender.send(FINANCE_EMAIL, "Pagamento recebido - reserva " + reservation.id(),
    23	                "Reserva " + reservation.id() + " (" + reservation.guest().name() + "): pagamento de "
    24	                        + TextFormat.money(reservation.amountPaid()) + ".\n");
    25	    }
    26	
    27	    @Override
    28	    public void cancelled(Reservation reservation, Room room) {
    29	        if (reservation.refund().signum() > 0) {
    30	            emailSender.send(FINANCE_EMAIL, "Reembolso - reserva " + reservation.id(),
    31	                    "Devolver " + TextFormat.money(reservation.refund()) + " para "
    32	                            + reservation.guest().name() + ".\n");
    33	        }
    34	    }
    35	}
