     9	/** The guest gets the receipt by e-mail when the reservation is confirmed. */
    10	public final class GuestConfirmationEmail implements ReservationListener {
    11	
    12	    static final String HOTEL_NAME = "Pousada Maré Alta";
    13	
    14	    private final EmailSender emailSender;
    15	
    16	    public GuestConfirmationEmail(EmailSender emailSender) {
    17	        this.emailSender = emailSender;
    18	    }
    19	
    20	    @Override
    21	    public void confirmed(Reservation reservation, Room room) {
    22	        ReservationReceipt receipt = new ReservationReceipt(reservation, room);
    23	        emailSender.send(reservation.guest().email(), "Reserva confirmada - " + HOTEL_NAME, body(reservation, receipt));
    24	    }
    25	
    26	    private static String body(Reservation reservation, ReservationReceipt receipt) {
    27	        return "Olá, " + reservation.guest().name() + "!\n\n"
    28	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
    29	                + receipt.text() + "\n"
    30	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
    31	                + "Até breve!\n";
    32	    }
    33	}
