4	     3	import hotel.rooms.Room;
5	     4	import java.math.BigDecimal;
6	     5	import java.math.RoundingMode;
7	     6	import java.time.LocalDate;
8	     7	import java.time.Month;
9	     8	
10	     9	/**
11	    10	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
12	    11	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
13	    12	 * (half-even) at every step.
14	    13	 */
15	    14	public final class PriceCalculator {
16	    15	
17	    16	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
18	    17	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
19	    18	
20	    19	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
21	    20	        int nights = 0;
22	    21	        BigDecimal subtotal = cents(BigDecimal.ZERO);
23	    22	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
24	    23	            subtotal = subtotal.add(nightPrice(room, night));
25	    24	            nights++;
26	    25	        }
27	    26	        BigDecimal discount = switch (ratePlan) {
28	    27	            case STANDARD -> cents(BigDecimal.ZERO);
29	    28	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
30	    29	        };
31	    30	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
32	    31	    }
33	    32	
34	    33	    BigDecimal nightPrice(Room room, LocalDate night) {
35	    34	        BigDecimal nightlyRate = room.nightlyRate();
36	    35	        if (isHighSeason(night)) {
37	    36	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
38	    37	        }
39	    38	        return cents(nightlyRate);
40	    39	    }
41	    40	
42	    41	    /** High season: from December 15 to the end of February, and the whole of July. */
43	    42	    static boolean isHighSeason(LocalDate date) {
44	    43	        Month month = date.getMonth();
45	    44	        return month == Month.JANUARY
46	    45	                || month == Month.FEBRUARY
47	    46	                || month == Month.JULY
48	    47	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
49	    48	    }
50	    49	
51	    50	    static BigDecimal cents(BigDecimal value) {
52	    51	        return value.setScale(2, RoundingMode.HALF_EVEN);
53	    52	    }
54	    53	}
