372	    23	    public String generate(YearMonth month) {
373	    24	        List<Reservation> withRevenue = new ArrayList<>();
374	    25	        for (Reservation reservation : store.all()) {
375	    26	            boolean keptMoney = reservation.amountKept().signum() > 0;
376	    27	            boolean startsInMonth = YearMonth.from(reservation.checkIn()).equals(month);
